def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 is None or v2 is None:
        return {
            "value": None,
            "trace": {
                "v1": v1,
                "v2": v2,
                "output_meta": {
                    "currency": None,
                    "scale": "ones",
                    "unit": "year"
                }
            }
        }

    if v1 > v2:
        value = 2017
    elif v2 > v1:
        value = 2018
    else:
        value = None

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "comparison": v2 - v1,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "year"
            }
        }
    }
